policies.statement:
// Reads: both agent identities may call the read tools. Order ownership is checked by the Lambda (Cedar cannot
// see Duffel data). Anything no policy permits is denied (AgentCore Policy is default deny).
permit (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"Duffel___search_flights",
    AgentCore::Action::"Duffel___get_order",
    AgentCore::Action::"Duffel___list_orders",
    AgentCore::Action::"Duffel___seat_map",
    AgentCore::Action::"Duffel___change_options",
    AgentCore::Action::"Duffel___bag_options"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DeskGateway" ||
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-FlightOpsGateway"
};

// Writes: only the Flight Ops identity, and only for a caller who passed identity verification this session.
// The confirmation turn ("yes" in a later message) is enforced in agent code by a Strands interrupt
// (common.WriteGate): Cedar cannot see turns.
permit (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"Duffel___book_offer",
    AgentCore::Action::"Duffel___change_order",
    AgentCore::Action::"Duffel___cancel_order",
    AgentCore::Action::"Duffel___add_bag"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-FlightOpsGateway" &&
  context.input.guest_verified == true
};

// Belt and braces: even if a broader permit is added later, the desk identity can never write.
forbid (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"Duffel___book_offer",
    AgentCore::Action::"Duffel___change_order",
    AgentCore::Action::"Duffel___cancel_order",
    AgentCore::Action::"Duffel___add_bag"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DeskGateway"
};

// The Disruption identity (Disruption agent and the read only Flight Ops it calls) may read one order and price
// date changes, nothing else on Duffel. Ownership of the order is still checked by the Lambda.
permit (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"Duffel___get_order",
    AgentCore::Action::"Duffel___change_options"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DisruptionGateway"
};

// The Disruption identity never writes, whatever other permits say: rebooking goes back through the desk's quote
// and confirmation with the Flight Ops identity.
forbid (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"Duffel___book_offer",
    AgentCore::Action::"Duffel___change_order",
    AgentCore::Action::"Duffel___cancel_order",
    AgentCore::Action::"Duffel___add_bag"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DisruptionGateway"
};

// TripIntel (public weather, holidays, FX; read only, no traveler data): any of the three agent identities.
// Deployed after the TripIntel target exists: the policy engine validates actions against the Gateway's tools.
permit (
  principal is AgentCore::IamEntity,
  action in [
    AgentCore::Action::"TripIntel___airport_weather",
    AgentCore::Action::"TripIntel___airport_forecast",
    AgentCore::Action::"TripIntel___destination_forecast",
    AgentCore::Action::"TripIntel___public_holidays",
    AgentCore::Action::"TripIntel___fx_convert"
  ],
  resource == AgentCore::Gateway::"arn:aws:bedrock-agentcore:us-east-1:437987386879:gateway/travelconcierge-traveldeskgateway-a4bksxcakf"
)
when {
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DeskGateway" ||
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-FlightOpsGateway" ||
  principal.id == "arn:aws:sts::437987386879:assumed-role/TravelConcierge-DisruptionGateway"
};
